-- Habilita Administracion y cambia exclusivamente al usuario solicitado.
begin;
create extension if not exists unaccent;
create or replace function public.usuario_responsable_valido(p_rol text,p_parent_id uuid) returns boolean language plpgsql stable security definer set search_path='' as $$declare permitidos text[];rol_padre text;estado_padre text;begin permitidos:=case public.usuario_rol_normalizado(p_rol) when 'administracion' then array[]::text[] when 'director_nacional' then array[]::text[] when 'director_zona' then array['director_nacional'] when 'jefe_ventas' then array['director_zona','director_nacional'] when 'jefe_equipo' then array['jefe_ventas','director_zona','director_nacional'] when 'agente' then array['jefe_equipo','jefe_ventas','director_zona','director_nacional'] else null end;if permitidos is null then return false;end if;if cardinality(permitidos)=0 then return p_parent_id is null;end if;if p_parent_id is null then return false;end if;select public.usuario_rol_normalizado(rol_usuario),public.usuario_rol_normalizado(coalesce(estado,'activo')) into rol_padre,estado_padre from public.usuarios where id=p_parent_id;return rol_padre=any(permitidos) and estado_padre not in('bloqueado','inactivo','desactivado');end$$;
do $$declare coincidencias integer;begin select count(*) into coincidencias from public.usuarios where lower(trim(nombre))='francisco javier' and lower(public.unaccent(trim(apellidos)))='parraga alvarez';if coincidencias<>1 then raise exception 'Se esperaba un unico Francisco Javier Parraga Alvarez y se encontraron %',coincidencias;end if;update public.usuarios set rol_usuario='administracion',parent_id=null where lower(trim(nombre))='francisco javier' and lower(public.unaccent(trim(apellidos)))='parraga alvarez';end$$;
commit;